#!/usr/bin/env python3
"""Helper script to send Chrome DevTools Protocol commands."""
import json
import sys
import websocket

WS_URL = "ws://localhost:1337/devtools/page/0C9FCAE157AE2FB31DDEAA0FDCB091F4"

def send(method, params=None):
    ws = websocket.create_connection(WS_URL, timeout=30)
    msg = {"id": 1, "method": method, "params": params or {}}
    ws.send(json.dumps(msg))
    while True:
        result = json.loads(ws.recv())
        if result.get("id") == 1:
            ws.close()
            return result

def evaluate(expr, await_promise=False):
    return send("Runtime.evaluate", {
        "expression": expr,
        "returnByValue": True,
        "awaitPromise": await_promise,
    })

if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "eval":
        expr = sys.argv[2]
        await_p = len(sys.argv) > 3 and sys.argv[3] == "await"
        print(json.dumps(evaluate(expr, await_p), indent=2))
    elif cmd == "navigate":
        print(json.dumps(send("Page.navigate", {"url": sys.argv[2]}), indent=2))
    elif cmd == "raw":
        method = sys.argv[2]
        params = json.loads(sys.argv[3]) if len(sys.argv) > 3 else {}
        print(json.dumps(send(method, params), indent=2))

